import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaMoon, FaSun } from 'react-icons/fa';
import './LandingPage.css';

function LandingPage() {
  const navigate = useNavigate();
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    document.body.className = darkMode ? 'dark' : 'light';
  }, [darkMode]);

  return (
    <div className="landing-container">
      <div className="overlay"></div>
      <div className="theme-toggle" onClick={() => setDarkMode(!darkMode)}>
        {darkMode ? <FaSun className="theme-icon" /> : <FaMoon className="theme-icon" />}
      </div>
      <div className="card">
        <h1 className="title">Diabetes App</h1>
        <p className="subtitle">Predict and Visualize with Ease</p>
        <div className="button-group">
          <button onClick={() => navigate('/visualization')} className="modern-button">
            Data Visualization
          </button>
          <button onClick={() => navigate('/prediction')} className="modern-button">
            Diabetes Prediction
          </button>
        </div>
      </div>
    </div>
  );
}

export default LandingPage;
